/// Auto-generated multilingual spec word dictionary
/// Covers 222 technical terms across 12 languages
library;

/// Translate a spec name/value using word-level dictionary.
/// Handles parenthetical suffixes: "Print Speed (Color)" → "Baskı Hızı (Renkli)"
String translateSpec(String text, String locale) {
  if (locale == 'en' || text.isEmpty) return text;

  // Handle parenthetical content: "Print Speed (Color)" → "Baskı Hızı (Renkli)"
  final parenMatch = RegExp(r'^(.*?)\s*\(([^)]+)\)\s*$').firstMatch(text);
  if (parenMatch != null) {
    final mainPart = parenMatch.group(1)!.trim();
    final parenContent = parenMatch.group(2)!.trim();
    if (mainPart.isNotEmpty) {
      final translatedMain = _translateInner(mainPart, locale);
      final translatedParen = _translateInner(parenContent, locale);
      final combined = '$translatedMain ($translatedParen)';
      return combined.isNotEmpty
          ? combined[0].toUpperCase() + combined.substring(1)
          : combined;
    }
  }

  return _translateInner(text, locale);
}

/// Internal word-by-word translation — no parenthesis handling.
String _translateInner(String text, String locale) {
  if (text.isEmpty) return text;

  // 1. Try exact match (case-insensitive)
  final exact = _dict[locale]?[text.toLowerCase()];
  if (exact != null) return _titleCase(exact);

  // 2. Try word-by-word translation with sliding window (3→2→1)
  final words = text.split(RegExp(r'[\s/&]+'));
  if (words.length <= 1) {
    final w = _dict[locale]?[text.toLowerCase().trim()];
    return _titleCase(w ?? text);
  }

  final result = <String>[];
  int i = 0;
  while (i < words.length) {
    bool found = false;
    // Try 3-word combo
    if (i + 2 < words.length) {
      final tri = '${words[i]} ${words[i+1]} ${words[i+2]}'.toLowerCase();
      final t = _dict[locale]?[tri];
      if (t != null) { result.add(t); i += 3; found = true; }
    }
    // Try 2-word combo
    if (!found && i + 1 < words.length) {
      final bi = '${words[i]} ${words[i+1]}'.toLowerCase();
      final t = _dict[locale]?[bi];
      if (t != null) { result.add(t); i += 2; found = true; }
    }
    // Single word
    if (!found) {
      final w = _dict[locale]?[words[i].toLowerCase().trim()];
      result.add(w ?? words[i]);
      i++;
    }
  }

  final translated = result.join(' ');
  return translated.isNotEmpty
      ? translated[0].toUpperCase() + translated.substring(1)
      : translated;
}

String _titleCase(String s) =>
    s.isNotEmpty ? s[0].toUpperCase() + s.substring(1) : s;

/// Translate spec values like "Yes", "No", "Available", etc.
String translateSpecValue(String value, String locale) {
  if (locale == 'en' || value.isEmpty) return value;
  // Use the same word-level algorithm as translateSpec
  return translateSpec(value, locale);
}

